        ("BEGIN { SUBSEP = \"-\"; a[1, 2] = 1; for (k in a) print k; b[1, 2] = \"x\"; for (k in b) { split(k, p, SUBSEP); print p[1], p[2] } print ((1, 2) in b), ((1, 3) in b), ((1 SUBSEP 2) in b) }",),
        ("BEGIN { a[1] = 1; a[\"1\"] = 2; print length(a), a[1], a[\"1\"], a[1.0] }",),
