# --- ulimit -----------------------------------------------------------------
def builtins_ulimit_normalize(channel, data):
    # Both shells read the same kernel, so they agree on every limit; but a
    # pinned answer carries the limits of the machine it was taken on, and
    # max user processes, pending signals and the hard open-file limit scale
    # with its memory and its init's defaults. They drifted on every ulimit
    # pin when the box rebooted into a new kernel. Five digits and up are
    # those; 1024, 8192 and the small ones stay compared.
    if channel == "stdout":
        return re.sub(rb"\b\d{5,}\b", b"<limit>", data)
    return data


# Bash and our shell share the wide letter set; dash has only -f -t -s -c -d -m
# -n -p -v (and -H/-S). Split so each mode is compared against a reference that
# accepts the same letters.
builtins_add(Utility(
    "ulimit",
    options=(Option("-H"), Option("-S"),
             Option("-a"), Option("-c"), Option("-d"), Option("-f"),
             Option("-l"), Option("-m"), Option("-n"), Option("-p"),
             Option("-s"), Option("-t"), Option("-u"), Option("-v"),
             Option("-x"), Option("-i"), Option("-q"), Option("-r"),
             Option("-e")),
    operands=((), ("100",), ("unlimited",), ("hard",), ("soft",)),
    stdin=("empty",), stderr="loose", modes=BASH,
    # A value is only ever given to one resource: applying it to a list would
    # set RLIMIT_AS or RLIMIT_NOFILE on the shell under test and the two sides
    # would then fail in different places for reasons that are not ulimit's.
    valid=lambda argv: sum(1 for w in argv if not w.startswith("-")) == 0
    or sum(1 for w in argv if w.startswith("-") and w not in ("-H", "-S", "-a")) <= 1,
    script=builtins_wrap("ulimit"), normalize=builtins_ulimit_normalize, max_flags=2))
builtins_add(Utility(
    "ulimit_posix",
    options=(Option("-H"), Option("-S"), Option("-a"), Option("-c"),
             Option("-d"), Option("-f"), Option("-m"), Option("-n"),
             Option("-p"), Option("-s"), Option("-t"), Option("-v")),
    operands=((), ("100",), ("unlimited",)),
    stdin=("empty",), stderr="loose", modes=ALL,
    # A value is only ever given to one resource: applying it to a list would
    # set RLIMIT_AS or RLIMIT_NOFILE on the shell under test and the two sides
    # would then fail in different places for reasons that are not ulimit's.
    valid=lambda argv: sum(1 for w in argv if not w.startswith("-")) == 0
    or sum(1 for w in argv if w.startswith("-") and w not in ("-H", "-S", "-a")) <= 1,
    script=builtins_wrap("ulimit"), normalize=builtins_ulimit_normalize, max_flags=2))

