# --- mapfile / readarray ----------------------------------------------------
def builtins_mapfile_script(name):
    def script(argv, stdin):
        return ("printf 'r0\\nr1\\nr2\\nr3\\nr4\\n' > recs\n"
                "arr=(old old old old)\n"
                + name + " " + builtins_words(argv) + " arr < recs\n"
                'printf "[%s] n:%s\\n" "$?" "${#arr[@]}"\n'
                'printf "<%s>\\n" "${arr[@]}"\n')
    return script


