def files_backup_cases(tool, words):
    """Every way a suffix reaches the backup name, crossed with every control
    word and each way the tool is told to make one, drawn per tool so a
    second tool is not the first one's cases under another name."""
    rng = random.Random(int.from_bytes(hashlib.sha256(
        ("backup:" + tool).encode()).digest()[:8], "little"))
    suffixes = ("_/../c", "/../c", "_//../c", "x/", "/", "x//", ".bak", "", "_/", "/c")
    controls = ((), ("-b",), ("--backup",), ("--backup=simple",), ("--backup=numbered",),
                ("--backup=existing",), ("--backup=none",))
    targets = (("a", "b"), ("a", "d"), ("a", "d/b"))
    cases = []
    for suffix in suffixes:
        for control in rng.sample(controls, 3):
            argv = tuple(words) + tuple(control)
            target = rng.choice(targets)
            cases.append({"fixture": "files_backup", "argv": argv + ("-S", suffix) + target})
            cases.append({"fixture": "files_backup", "argv": argv + ("--suffix=" + suffix,) + target})
            cases.append({"fixture": "files_backup", "argv": argv + target,
                          "env": (("SIMPLE_BACKUP_SUFFIX", suffix),)})
    #   The source is the destination's own backup name: backing up would
    #   move the destination over the source, so a simple or existing
    #   backup is refused and a numbered one is not.
    for source in ("b~", "./b~", "b.bak", "e", "d/../b~"):
        for control in (("-b",), ("--backup=simple",), ("--backup=existing",), ("--backup=numbered",),
                        ("-S", ".bak"), ("--suffix=.bak", "--backup=simple"), ("-b", "-S", "~")):
            cases.append({"fixture": "files_backup", "argv": tuple(words) + control + (source, "b")})
    #   VERSION_CONTROL decides whenever no --backup word does, however the
    #   backup was asked for; a word given decides over it, and a word it
    #   does not know is refused under its own name.
    for control in ("numbered", "t", "simple", "never", "existing", "nil", "none", "off", "bogus", ""):
        for asked in rng.sample(((("-b",), ("--backup",), ("-S", ".s"), ("--backup=",),
                                  ("--backup=simple",), ("-b", "--backup=numbered"))), 3):
            cases.append({"fixture": "files_backup", "argv": tuple(words) + asked + rng.choice(targets),
                          "env": (("VERSION_CONTROL", control),)})
    return tuple(cases)


