_TEXT_GREP_OPERAND_PATTERNS = {"alpha", "a", "needle", "x", "^$", "--nosuchflag", "", "alpha\nbeta",
                               "beta", "-x"}


def text_has_pattern(argv, letters, longs, operand_words):
    for index, word in enumerate(argv):
        if word in letters or any(word.startswith(name) for name in longs):
            return True
    return any(word in operand_words for word in argv)


#       -f - makes the whole input one pattern file. Past a few kilobytes on
#       one line that is a pattern GNU spends the runner's four CPU seconds
#       compiling -- killed, and so no oracle at all, sooner or later
#       depending on the machine -- so those inputs are not patterns here.
_TEXT_GREP_BIG_INPUTS = ("edge_65535", "edge_65536", "edge_65537", "long", "many_lines", "text_backtrack")


def text_grep_valid(argv, stdin=None):
    if stdin in _TEXT_GREP_BIG_INPUTS and any(
            (word == "-" and index and argv[index - 1] == "-f") or word in ("--file=-",)
            for index, word in enumerate(argv)):
        return False
    return text_has_pattern(argv, ("-e", "-f"), ("--regexp", "--file"), _TEXT_GREP_OPERAND_PATTERNS)


_TEXT_GREP_VALUED_SHORT = "efmABCdDX"
_TEXT_GREP_VALUED_LONG = ("--after-context", "--before-context", "--binary-files", "--context",
                          "--devices", "--directories", "--exclude", "--exclude-dir", "--exclude-from",
                          "--file", "--group-separator", "--include", "--label", "--max-count",
                          "--regexp")


def text_grep_walks(argv):
    """Whether a grep argv asks to walk directories: -r or -R, alone or in a
    cluster, their long names, or recurse (or an abbreviation GNU's argmatch
    takes) for -d or --directories, anywhere before --. A value is skipped as
    a value, so -e -r and -Dread are not recursion. A later -d skip is not
    read as taking recursion back: a candidate that walks all the same is the
    very answer whose pin must not follow readdir order."""
    def recurse(value):
        return len(value) >= 3 and "recurse".startswith(value)
    at = 0
    while at < len(argv):
        word = argv[at]
        at += 1
        if word == "--":
            return False
        if word in ("--recursive", "--dereference-recursive"):
            return True
        if word.startswith("--"):
            name, glued, value = word.partition("=")
            if name in _TEXT_GREP_VALUED_LONG and not glued:
                value = argv[at] if at < len(argv) else ""
                at += 1
            if name == "--directories" and recurse(value):
                return True
            continue
        if not word.startswith("-") or word == "-":
            continue
        for index, letter in enumerate(word[1:], 1):
            if letter in "rR":
                return True
            if letter in _TEXT_GREP_VALUED_SHORT:
                value = word[index + 1:]
                if not value:
                    value = argv[at] if at < len(argv) else ""
                    at += 1
                if letter == "d" and recurse(value):
                    return True
                break
    return False


