#       Files holding a NUL where GNU grep reads its buffers, for its binary
#       rule: GNU looks for a NUL in each read of 98304 bytes before searching
#       it, and from the first read holding one prints nothing more, saying
#       "binary file matches" once a line is selected. early_nul has its NUL
#       in the first read, after a matching line; late_nul in the second, so
#       the line before it prints and the ones after do not. A set of its own
#       so no pinned row of the text set moves.
FIXTURES["text_binary"] = {
    **FIXTURES["text"],
    "early_nul": b"alpha first\n" + (b"y" * 99 + b"\n") * 700 + b"\0\nalpha after\n",
    "late_nul": b"alpha first\n" + (b"y" * 99 + b"\n") * 1000 + b"\0\nalpha after\nalpha more\n",
    # Where the NULs end lines: z1's eight lines are ab, cd, ab, ab, three
    # empty ones and ef; z2's first x and y are two lines.
    "z1": b"ab\0cd\nab\0ab\n\0\0\nef\n",
    "z2": b"x\0y\nxy\n",
    "longnul": b"struct " + b"x" * 200000 + b"\0 struct\nstruct tail\n",
    "nulrun": b"a\n" + b"\0" * 5000 + b"\nb\n",
}

