#       The half of GNU's binary rule that a locale decides: in UTF-8 a line
#       holding a byte that is no character is kept from the output -- a
#       selected line, a line of context or an -o match -- and the file says
#       "binary file matches" once, though -c, -l and -I answer as before. The
#       grammar walk runs in the C locale, so these cells run as a check,
#       both programs under LC_ALL=C.UTF-8 in one directory.
_TEXT_GREP_ENCODING_FILES = {
    "bad1": b"struct \xff\nstruct ok\n",
    "bad2": b"ok one\nstruct \xff\nstruct two\nstruct three\n",
    "bad3": b"struct fine\nzzz \xff\nstruct after\n",
    "bad4": b"struct \xc3\nstruct \xc3\xa9\n",
    "bad5": b"struct a\nstruct \xff b\n\0\nstruct c\n",
    "bad8": b"struct one\nctx \xff\nstruct two\n",
    "badz": b"struct \xff\0struct ok\0",
}

_TEXT_GREP_ENCODING_CASES = (
    ("-n", "struct", "bad1"), ("-n", "struct", "bad2"), ("-n", "struct", "bad3"), ("-n", "zzz", "bad3"),
    ("-n", "struct", "bad4"), ("-n", "struct", "bad5"), ("-c", "struct", "bad2"), ("-l", "struct", "bad1"),
    ("-v", "-n", "zzz", "bad2"), ("-o", "-n", "struct", "bad2"), ("-A1", "-n", "ok", "bad2"),
    ("-a", "-n", "struct", "bad2"), ("-I", "-n", "struct", "bad2"), ("-I", "-c", "struct", "bad2"),
    ("-z", "struct", "badz"), ("-A1", "-n", "one", "bad8"), ("-B1", "-n", "two", "bad8"),
    ("-C1", "-n", "struct", "bad8"), ("--color=always", "struct", "bad2"), ("-I", "-A1", "-n", "one", "bad8"),
    ("-n", "struct", "bad2", "bad2"), ("-v", "-c", "zzz", "bad2"), ("-H", "-x", "struct two", "bad2"),
    ("-m1", "-n", "struct", "bad1"), ("-F", "-n", "struct", "bad2"), ("-s", "struct", "bad1"),
)


def text_grep_encoding(farm):
    import shutil
    import subprocess
    import tempfile

    reference = shutil.which("grep", path=os.defpath)
    candidate = Path(farm) / "grep"
    if not reference or not candidate.exists():
        return 0, 1, ["the UTF-8 grep cells need both a reference and a candidate grep"]
    environment = dict(os.environ, LC_ALL="C.UTF-8")
    environment.pop("GREP_COLORS", None)
    passed = 0
    notes = []
    with tempfile.TemporaryDirectory(prefix="grep-encoding-") as temporary:
        for name, data in _TEXT_GREP_ENCODING_FILES.items():
            (Path(temporary) / name).write_bytes(data)
        for argv in _TEXT_GREP_ENCODING_CASES:
            answers = []
            for binary in (reference, candidate):
                result = subprocess.run(["grep", *argv], executable=str(binary), cwd=temporary,
                                        env=environment, stdin=subprocess.DEVNULL,
                                        stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5)
                answers.append((result.returncode, result.stdout, result.stderr))
            if answers[0] == answers[1]:
                passed += 1
            else:
                notes.append(f"grep {shlex.join(argv)} under C.UTF-8: "
                             f"reference={answers[0]!r}, candidate={answers[1]!r}")
    return passed, len(_TEXT_GREP_ENCODING_CASES), notes


#       What each filter says about an input it could not open or could
#       not read, byte for byte. Every other text case compares a diagnostic
#       as present or absent, so a filter that named a directory "Read error"
#       where GNU names the reason, or wrote a newline in a file name straight
#       to the terminal where coreutils quotes it, agreed with the reference
#       everywhere. The tools here are the ones the text lane walks, each
#       with the words it needs in front of a file operand.
_TEXT_FAILURE_TOOLS = (
    ("cat",), ("wc",), ("cut", "-c1"), ("nl",), ("od",), ("uniq",), ("paste",), ("fold",),
    ("expand",), ("unexpand",), ("base64",), ("base32",), ("pr",), ("ptx",), ("sum",),
    ("head",), ("tail",), ("fmt",), ("tac",), ("sort",), ("sed", "p"), ("rev",),
    ("grep", "x"), ("tsort",), ("cksum",), ("md5sum",), ("shuf",), ("tee",),
    ("head", "-c1"), ("tail", "-c1"), ("wc", "-l"), ("sort", "-m"), ("uniq", "-c"),
    ("tr", "a", "b"),
)

#       The two programs that read two inputs side by side, each shape of
#       failing one or both: GNU stops at the first that fails, and names
#       only that one.
_TEXT_FAILURE_PAIRED = (("comm",), ("join",), ("comm", "-3"), ("join", "-a1"))

#       Names that differ only in what a quoting has to do with them: a
#       plain one, a blank, each quote, a newline, a tab, an escape, a
#       backslash, a byte outside ASCII, a dollar, and a newline at either
#       end, which is where a shell-escaped name loses its outer quote.
_TEXT_FAILURE_NAMES = (
    b"missing", b"sp ace", b"new\nline", b"q'x", b'd"q', b"tab\tx", b"e\x1bx", b"b\\s",
    b"h\xc3\xa9", b"a$b", b"\nlead", b"trail\n", b"q'\nx",
)

#       Where the answer is still this tool's own, and why: rev takes - as a
#       file name, and GNU tac's reason for a directory is the filesystem's
#       -- Invalid argument on ext4, Is a directory on tmpfs -- from a call
#       that is not the seek and read its source names.
_TEXT_FAILURE_KNOWN = {
    ("rev", "stdin-directory"), ("tac", "directory"), ("tac", "stdin-directory"),
}


def text_failure_cases():
    cases = []
    for tool in _TEXT_FAILURE_TOOLS:
        for name in _TEXT_FAILURE_NAMES:
            cases.append((tool, "missing", (name,), None))
            cases.append((tool, "missing-after", (b"a.txt", name), None))
        for name in (b"dir", b"d ir", b"new\ndir", b"q'dir"):
            cases.append((tool, "directory", (name,), None))
        cases.append((tool, "stdin-directory", (b"-",), b"dir"))
        cases.append((tool, "stdin-directory", (), b"dir"))
    for tool in _TEXT_FAILURE_PAIRED:
        for name in (b"dir", b"q'dir", b"new\ndir"):
            cases.append((tool, "directory-first", (name, b"a.txt"), None))
            cases.append((tool, "directory-second", (b"a.txt", name), None))
            cases.append((tool, "directory-both", (name, name), None))
        for name in _TEXT_FAILURE_NAMES[:4]:
            cases.append((tool, "missing-both", (name, b"a.txt", ), None))
            cases.append((tool, "missing-both", (name, name + b"2"), None))
        cases.append((tool, "stdin-directory", (b"-", b"a.txt"), b"dir"))
        cases.append((tool, "stdin-directory", (b"a.txt", b"-"), b"dir"))
    return [case for case in cases if (case[0][0], case[1]) not in _TEXT_FAILURE_KNOWN]


def text_file_failures(farm):
    """Every text tool on a missing name, a directory and a standard input
    that is a directory, over names that need each kind of quoting, against
    GNU with the diagnostic compared exactly."""
    import shutil
    import subprocess
    import tempfile
    from concurrent.futures import ThreadPoolExecutor

    cases = text_failure_cases()
    names = sorted({case[0][0] for case in cases})
    reference = {tool: shutil.which(tool, path=os.defpath) for tool in names}
    candidate = {tool: Path(farm) / tool for tool in names}
    if not all(reference.values()) or not all(p.exists() for p in candidate.values()):
        return 0, 1, ["text failure checks need " + ", ".join(names) + " on both sides"]

    def run(case, side):
        tool, _, operands, stdin = case
        with tempfile.TemporaryDirectory(prefix="text-failures-") as directory:
            Path(directory, "a.txt").write_bytes(b"alpha\nbeta\n")
            for name in (b"dir", b"d ir", b"new\ndir", b"q'dir"):
                os.mkdir(os.path.join(os.fsencode(directory), name))
            source = os.open(os.path.join(directory, stdin.decode()), os.O_RDONLY) if stdin \
                else subprocess.DEVNULL
            try:
                binary = str(side[tool[0]])
                result = subprocess.run([tool[0].encode(), *(a.encode() for a in tool[1:]), *operands],
                                        executable=binary, cwd=directory,
                                        env={"PATH": os.defpath, "LC_ALL": "C", "TZ": "UTC0"},
                                        stdin=source, stdout=subprocess.PIPE,
                                        stderr=subprocess.PIPE, timeout=10)
            finally:
                if stdin:
                    os.close(source)
            #       tee copies standard input into its operands and ptx and
            #       sort -m hold nothing back, so the directory's path cannot
            #       reach either stream; only the program's own spelling of
            #       its path is taken out of the diagnostic.
            return result.returncode, result.stdout, _stderr_exact(result.stderr)

    def compare(case):
        return case, run(case, reference), run(case, candidate)

    passed, notes = 0, []
    with ThreadPoolExecutor(max_workers=8) as pool:
        for case, want, got in pool.map(compare, cases):
            if want == got:
                passed += 1
            elif len(notes) < 40:
                tool, kind, operands, stdin = case
                shown = " ".join([*tool, *(repr(o)[1:] for o in operands)])
                notes.append(f"{shown} ({kind}): GNU {want!r} ours {got!r}")
    return passed, len(cases), notes


TEXT_CHECKS = (text_grep_encoding, text_file_failures)

