def _text_write_valid(argv):
    return (len(argv) >= 3 and argv[0] in _TEXT_WRITE_TOOLS and
            argv[1] in _TEXT_WRITE_SOURCES and argv[2] in _TEXT_WRITE_TARGETS)


def _text_write_script(argv, stdin_name):
    setup, redirect, after = _TEXT_WRITE_TARGETS[argv[2]]
    command = _TEXT_WRITE_SOURCES[argv[1]].format(words=ul_words(argv[3:]), target=redirect)
    body = _TEXT_WRITE_PROLOGUE + setup + command + "\nstatus=$?\n" + after + "exit $status\n"
    return ul_live(argv[0], body, wrap="unshare -Urm")


#       Inputs a regular file in the fixture cannot stand for: a pipe, a pipe
#       that pauses until the tool has written what it holds, a file two
#       tools read in turn through one descriptor, a file read from an offset
#       another tool left, and a pipe too large to hold in memory, into a
#       temporary directory that has room and one that has not. The engine
#       feeds every other case from a seekable file, so none of these shapes
#       was ever reached. The words are the tool, the shape, and then its own
#       options; each case runs in a mount namespace of its own.
_TEXT_STREAM_PROLOGUE = ("env mkdir m && env mount -t tmpfs -o size=64k tmpfs m || "
                         "{ echo 'no tmpfs here'; exit 0; }\n"
                         "env seq 1 300000 > numbers\n"
                         "printf 'abcdef\\nghij\\001kl\\tm\\n' > six\n")
_TEXT_STREAM_SOURCES = {
    "pipe": "env cat numbers | {{ run {words}; echo \"status $?\"; }} | env md5sum",
    "file": "{{ run {words} numbers; echo \"status $?\"; }} | env md5sum",
    "offset": "{{ env head -n 7 > /dev/null; run {words}; echo \"status $?\"; }} < numbers | env md5sum",
    "shared": "{{ run {words}; run {words}; echo \"status $?\"; }} < six",
    "sharedpipe": "env cat six | {{ run {words}; echo \"status $?\"; env cat; }}",
    "big": "env seq 1 1000000 | {{ run {words}; echo \"status $?\"; }} | env md5sum",
    "full": ("export TMPDIR=$PWD/m\n"
             "env seq 1 1000000 | {{ run {words}; echo \"status $?\"; }} | env md5sum"),
    #   The writer pauses after its first line until the reader has had
    #   that line, so a tool that keeps what it has read until the input
    #   ends never gives it, and the case runs out of time.
    "live": ("env mkfifo go\n"
             "{{ printf 'one\\t\\001\\n'; read -r x < go; printf 'two\\n'; }} | "
             "{{ run {words}; echo \"status $?\"; }} | {{ env head -n 1; echo > go; env cat; }}"),
}
_TEXT_STREAM_CASES = (
    ("tac", "pipe"), ("tac", "file"), ("tac", "offset"), ("tac", "big"), ("tac", "full"),
    ("tac", "pipe", "-b"), ("tac", "big", "-s", "0"), ("tac", "full", "-r", "-s", "[05]"),
    ("tac", "sharedpipe"),
    ("od", "shared", "-An", "-N3", "-c"), ("od", "shared", "-N4", "-tx1"),
    ("od", "shared", "-An", "-j2", "-N2", "-c"), ("od", "shared", "-An", "-N3", "-S1"),
    ("od", "sharedpipe", "-An", "-N3", "-c"), ("od", "offset", "-An", "-tx1"),
    ("cat", "live"), ("cat", "live", "-v"), ("cat", "live", "-n"), ("cat", "live", "-E"),
    ("cat", "live", "-A"), ("cat", "live", "-s"), ("cat", "live", "-b"), ("cat", "live", "-T"),
    ("cat", "pipe", "-n"), ("cat", "big", "-v"), ("cat", "offset", "-n"),
    ("head", "shared", "-c", "3"), ("head", "shared", "-n", "1"),
    ("wc", "offset"), ("wc", "offset", "-c"), ("nl", "pipe"),
)
_TEXT_STREAM_TOOLS = ("tac", "cat", "od", "head", "wc", "nl")


def _text_stream_valid(argv):
    return (len(argv) >= 2 and argv[0] in _TEXT_STREAM_TOOLS and
            argv[1] in _TEXT_STREAM_SOURCES)


def _text_stream_script(argv, stdin_name):
    command = _TEXT_STREAM_SOURCES[argv[1]].format(words=ul_words(argv[2:]))
    body = _TEXT_STREAM_PROLOGUE + command + "\n"
    return ul_live(argv[0], body, wrap="unshare -Urm")


#       tail -f, -F and --follow, which never end on their own: every cell
#       names a writer with --pid, and the writer waits (bounded) for each
#       step to show in tail's output or diagnostics before it takes the
#       next, so what tail says does not hang on when it was scheduled.
#       -n +1 prints the whole file whenever tail got to it. The writer is
#       started from a subshell that exits at once, so init reaps it: GNU
#       counts a zombie as alive, and a shell that only reaps a background
#       job when it next waits would leave tail waiting for ever. Each cell runs
#       with inotify and again with ---disable-inotify, GNU's hidden switch
#       for the polling loop; both must say the same.
_TEXT_FOLLOW_PROLOGUE = (
    "waitfor() { i=0; while ! env grep -q \"$1\" \"$2\" 2>/dev/null; do i=$((i+1)); "
    "[ $i -gt 150 ] && return 1; env sleep .02; done; }\n"
    "fast='-s.1 --max-unchanged-stats=1'\n")
_TEXT_FOLLOW_SCRIPTS = {
    "append": ("printf 'a\\nb\\n' > f\n"
               "( { waitfor b out; printf 'c\\n' >> f; waitfor c out; printf 'd\\n' >> f; waitfor d out; } & echo $! > wp; )\nw=$(env cat wp)\n"
               "run -f $fast --pid=$w -n +1 $mode f > out 2> err\n"),
    "truncated": ("printf 'a\\nb\\n' > f\n"
                  "( { waitfor b out; printf 'x\\n' > f; waitfor x out; } & echo $! > wp; )\nw=$(env cat wp)\n"
                  "run -f $fast --pid=$w -n +1 $mode f > out 2> err\n"),
    "descriptor": ("printf 'a\\nb\\n' > f\n"
                   "( { waitfor b out; env mv f g; printf 'c\\n' >> g; waitfor c out; } & echo $! > wp; )\nw=$(env cat wp)\n"
                   "run -f $fast --pid=$w -n +1 $mode f > out 2> err\n"),
    "name": ("printf 'a\\nb\\n' > f\n"
             "( { waitfor b out; env mv f g; waitfor inaccessible err; printf 'n\\n' > f; waitfor n out;"
             " printf 'o\\n' >> f; waitfor o out; } & echo $! > wp; )\nw=$(env cat wp)\n"
             "run -F $fast --pid=$w -n +1 $mode f > out 2> err\n"),
    "appears": ("( { waitfor 'cannot open' err; printf 'm\\n' > late; waitfor m out; } & echo $! > wp; )\nw=$(env cat wp)\n"
                "run -F $fast --pid=$w -n +1 $mode late > out 2> err\n"),
    "headers": ("printf 'a\\n' > f; printf 'b\\n' > g\n"
                "( { waitfor b out; printf 'c\\n' >> f; waitfor c out; printf 'e\\n' >> g; waitfor e out; } & echo $! > wp; )\nw=$(env cat wp)\n"
                "run -f $fast --pid=$w -n +1 $mode f g > out 2> err\n"),
    "stdin-pipe": ("printf 'a\\nb\\nc\\n' | run -f $fast -n 1 $mode > out 2> err\n"),
    "dead": ("run -F $fast --pid=2147483647 $mode a.txt missing > out 2> err\n"),
}
_TEXT_FOLLOW_CASES = tuple((name, mode) for name in _TEXT_FOLLOW_SCRIPTS
                           for mode in ("inotify", "polling"))


def _text_follow_script(argv, stdin_name):
    mode = "mode=" + ("---disable-inotify" if argv[1] == "polling" else "''") + "\n"
    body = (_TEXT_FOLLOW_PROLOGUE + mode + _TEXT_FOLLOW_SCRIPTS[argv[0]] + "status=$?\n" +
            "env cat out; echo ---; env cat err\nenv rm -f f g out err late wp\nexit $status\n")
    return ul_live("tail", body)


def _text_follow_valid(argv):
    return len(argv) == 2 and argv[0] in _TEXT_FOLLOW_SCRIPTS


#       --help and --version where GNU's getopt finds them: anywhere before
#       -- for a permuting tool, up to the first operand for the ones GNU
#       parses with a leading + (and for every tool under POSIXLY_CORRECT),
#       and only alone for expr; a letter's value hides the word after it.
#       The texts differ from GNU's by design, so a case compares whether
#       anything was printed, the status, and the status with standard
#       output on /dev/full, where each tool fails with its own number.
#       The words are the tool, then POSIX or - for the environment, then
#       the tool's words.
_TEXT_META_CASES = tuple(
    (tool, "-") + words
    for tool in ("yes", "sleep", "tsort", "cksum", "dd", "hostid", "link", "logname",
                 "unlink", "users", "whoami", "cat", "sort", "ls", "tty", "wc", "printenv")
    for words in (("BEFORE", "--version"), ("BEFORE", "--help", "AFTER"),
                  ("--", "--help"), ("--help",), ("--version",))) + (
    ("yes", "POSIX", "BEFORE", "--help"), ("sort", "POSIX", "BEFORE", "--version"),
    ("cat", "POSIX", "-n", "--help"),
    ("env", "-", "yes", "--version"), ("env", "-", "--help"), ("env", "-", "-u", "X", "--help"),
    ("env", "-", "-i", "--version"), ("timeout", "-", "-s", "INT", "--help"),
    ("timeout", "-", "5", "yes", "--help"), ("nice", "-", "-n", "1", "--version"),
    ("nice", "-", "yes", "--version"), ("stdbuf", "-", "-o", "L", "--help"),
    ("stdbuf", "-", "--help"), ("seq", "-", "-1", "--help"), ("seq", "-", "-s", ",", "--help"),
    ("seq", "-", "1", "--version"), ("basename", "-", "a", "--help"),
    ("basename", "-", "-s", "x", "--help"), ("tr", "-", "a", "--help"),
    ("tr", "-", "-d", "--version"), ("expr", "-", "--help"), ("expr", "-", "1", "--help"),
    ("expr", "-", "--version", "1"), ("nohup", "-", "--version"), ("nohup", "-", "--help"),
    ("cut", "-", "-d", "--help", "-f1"), ("cut", "-", "-f1", "--help"),
    ("head", "-", "-n", "--help"), ("head", "-", "-n1", "--version"),
    ("sort", "-", "-k", "1", "--help"), ("sort", "-", "-o", "--help"),
    ("date", "-", "-d", "--help"), ("date", "-", "+%s", "--version"),
    ("ls", "-", "-w", "--help"), ("ls", "-", "-w80", "--help"),
    ("printenv", "-", "HOME", "--help"), ("chroot", "-", "--help"),
)


def _text_meta_valid(argv):
    return len(argv) >= 3 and argv[1] in ("POSIX", "-")


def _text_meta_script(argv, stdin_name):
    words = ul_words(argv[2:])
    posix = "export POSIXLY_CORRECT=1\n" if argv[1] == "POSIX" else ""
    body = (posix +
            "{ run " + words + " 2>/dev/null < /dev/null; echo $? > st; } | env head -c 100000 > out\n"
            "test -s out && echo printed\n"
            "echo \"status $(env cat st)\"\nenv rm -f out st\n"
            "run " + words + " > /dev/full 2>/dev/null < /dev/null\n"
            "echo \"full $?\"\nstatus=0\nexit $status\n")
    return ul_live(argv[0], body)


