# ---------------------------------------------------------------------------
#       Small helpers for the grammars.
# ---------------------------------------------------------------------------

def ul_flags(*spells):
    return tuple(Option(spell) for spell in spells)


def ul_has(argv, *spells):
    for word in argv:
        for spell in spells:
            if word == spell or (spell.startswith("--") and word.startswith(spell + "=")) or \
                    (not spell.startswith("--") and len(spell) == 2 and word.startswith(spell)
                     and not word.startswith("--")):
                return True
    return False


def ul_needs_pid(argv):
    """Listing every process or lock on a busy box is not an oracle."""
    return ul_has(argv, "-p", "--pid", "--task", "-H", "--list-columns", "--dump-counters")


def ul_waitpid_valid(argv):
    """A live pid needs a timeout that expires, or neither tool ever
    returns and the case has no oracle."""
    live = any(word in ("1", "1:1", "+1", " 1") for word in argv)
    if not live:
        return True
    # The last spelling wins, so an earlier expiring timeout says nothing:
    # `--timeout=.01 -t 0` waits forever and has no oracle.
    last = None
    for index, word in enumerate(argv):
        if word in ("-t", "--timeout") and index + 1 < len(argv):
            last = argv[index + 1]
        elif word.startswith("-t") and len(word) > 2:
            last = word[2:]
        elif word.startswith("--timeout="):
            last = word[len("--timeout="):]
    if last is None:
        return False
    try:
        return float(last) > 0
    except ValueError:
        return True


def ul_lsns_live_valid(argv):
    return ul_has(argv, "-o", "--output") and not any("COMMAND" in word for word in argv)


