CANVAS_ROUTINES = ("canvas_rect_fill", "canvas_row_blit", "canvas_glyph",
                   "canvas_glyph2", "canvas_cell", "canvas_cell2", "canvas_cells",
                   "canvas_cell_wide", "canvas_cell2_wide", "canvas_row_blit_wide",
                   "canvas_cells_wide", "canvas_rect_fill_wide", "canvas_glyph_wide")


def canvas_assembly(library, arch):
    """The Canvas pixel loops for one machine, as a .S lifted out of lib.c.

    lib.c assembles them only into a kernel build with Canvas, so no
    user-space build of it carries them. A body is the lines between ASM_FUNC(name) and
    ASM_END(name) in the machine's block: C string literals, ASM_RET and
    comments. The strings are decoded rather than transcribed, so what the
    check runs is the text lib.c holds, and anything else in a body stops
    the lift instead of being guessed at.

    Each body is emitted after .balign 16, which need not be where the kernel
    build places it: the lift is for correctness, never the timing reference.
    """
    block = {"x86_64": "X64", "amd64": "X64", "aarch64": "ARM64",
             "arm64": "ARM64", "riscv64": "RISCV64"}.get(arch)
    if block is None:
        sys.exit("canvas assembly: lib.c has no block for %s" % arch)
    lines = Path(library).read_text().split("\n")
    owner, current = [], None
    for line in lines:
        selected = re.match(r"^#(el)?if (X64|ARM64|RISCV64)\b", line.strip())
        if selected:
            current = selected.group(2)
        owner.append(current)
    piece = re.compile(r'\s*("(?:\\.|[^"\\])*"|ASM_RET\b|//.*$)')
    out = [".text"]
    for name in CANVAS_ROUTINES:
        begins = [i for i, line in enumerate(lines)
                  if line.strip() == "ASM_FUNC(%s)" % name and owner[i] == block]
        if len(begins) != 1:
            sys.exit("canvas assembly: %d %s ASM_FUNC(%s) in %s"
                     % (len(begins), block, name, library))
        end = next((i for i in range(begins[0] + 1, len(lines))
                    if lines[i].strip().startswith(("ASM_FUNC(", "ASM_END("))), None)
        if end is None or lines[end].strip() != "ASM_END(%s)" % name:
            sys.exit("canvas assembly: ASM_FUNC(%s) has no ASM_END" % name)
        body = []
        for number in range(begins[0] + 1, end):
            line, at = lines[number], 0
            while line[at:].strip():
                found = piece.match(line, at)
                if not found:
                    sys.exit("canvas assembly: lib.c:%d is not a string, "
                             "ASM_RET or a comment: %s" % (number + 1, line.strip()))
                token = found.group(1)
                if token == "ASM_RET":
                    body.append("ret\n")
                elif token.startswith('"'):
                    body.append(ast.literal_eval(token))
                at = found.end()
        # A wide body's section carries the V extension on riscv64; the lift
        # says so around the body instead.
        vector = block == "RISCV64" and name.endswith("_wide")
        out += ([".option push", ".option arch, +v"] if vector else []) + [
                ".globl %s" % name, ".type %s, %%function" % name, ".balign 16",
                "%s:" % name, "".join(body).rstrip("\n"), ".size %s, .-%s" % (name, name)] + (
                [".option pop"] if vector else [])
    return "\n".join(out) + "\n"


def harness_core_state(argv):
    """Kernel snapshot allocation and Canvas geometry, with syscall/DRM-free mocks."""
    root = HARNESS_ROOT
    core = (root / "src/moonwater/core.c").read_text()
    # The bind subsystem and the machine script moved out of core.c into
    # moonwater.c; core.c includes it. The slices below follow them.
    moonwater = (root / "src/moonwater/moonwater.c").read_text()
    canvas = (root / "src/canvas/canvas.c").read_text()
    pane = canvas_part(canvas, "pane")
    compose = canvas_part(canvas, "compose")
    console = canvas_part(canvas, "console")
    drag = canvas_part(canvas, "drag")
    output = canvas_part(canvas, "output")
    pointer = canvas_part(canvas, "pointer")
    keys = canvas_part(canvas, "keys")
    spark = (root / "src/moonwater/spark.c").read_text()
    # The machine script this build bakes into the module. The scanner that
    # decides which rows the machine process owns is compiled here for real,
    # so the shipped file is scanned here for real as well: an edit to it that
    # stops arming the power button is a red check rather than a dead button.
    shipped_machine = (root / "main.moonwater.sh").read_text()
    assert shipped_machine.isascii(), "the machine script is ASCII"


    def section(source, first, following):
        return source[source.index(first):source.index(following)]


    def canvas_sources(work, arch):
        paint = canvas_part(canvas, "paint")
        text = canvas_part(canvas, "text")
        window = (root / "src/canvas/window.c").read_text()
        cells = section(window, "// The colour an index names", "#define WINDOW_CELL_BOLD")
        cells += section(canvas, "#define target_mark(pixels)",
                         "// The border and titlebar")
        cells += section(canvas, "struct target\n", "static void target_row")
        cells += section(compose, "struct shape\n", "static _Bool shape_span")
        cells += paint[paint.index("static CONST int round_inset"):]
        cells += section(compose, "static _Bool shape_span", "static void shape_blit")
        cells += section(canvas, "enum\n{", "/*\n        A pane")
        cells += section(paint, "static const u32 canvas_ink", "/*\n        A bitmap,")
        cells += section(paint, "static void bits_draw", "// xrgb8888")
        cells += section(text, "static const struct font_desc", "/*\n        Where one line ends.")
        cells += section(compose, "#define BX_N 1u", "/*\n        One cell, background and glyph together.")
        cells += section(compose, "static void cell_draw", "/*\n        A window made of text.\n\n        The rows")
        (work / "canvas-cells.inc").write_text(cells)
        (work / "canvas-ring.inc").write_text(section(compose, "static void compose_cells", "/*\n        The bar down the right of a window"))
        geometry = section(canvas, "static inline PURE _Bool drm_rects_overlap", "// The border and titlebar")
        geometry += section(canvas, "static void pane_frame", "// Which edges")
        geometry += "#define compose_cells compose_cells_pixels\n"
        geometry += section(compose, "static void compose_cells", "/*\n        The bar down the right of a window")
        #   The close button is not this harness's subject, and asking for
        #   its square needs a shared page the pane mocked here does not
        #   have. Saying there is never one leaves the titlebar drawn exactly
        #   as it was before there was a button to draw -- which is the thing
        #   these checks are about.
        geometry += ("static _Bool pane_close_box(struct pane *p,int *x,"
                     "int *y,int *side)\n"
                     "{ (void)p;(void)x;(void)y;(void)side; return 0; }\n"
                     "static const unsigned char close_bits[8] = {0};\n")
        geometry += section(compose, "struct pane_bar_geometry", "/*\n        The desktop, everywhere")
        geometry += "#undef compose_cells\n"
        geometry += section(drag, "static void bar_move", "/*\n        Filling the screen")
        (work / "canvas-pane.inc").write_text(geometry)
        # The renderer's own assembly bodies. lib.c assembles them only into
        # a kernel build with Canvas, so they are lifted out of it rather than linked.
        target = work / "canvas.S"
        target.write_text(canvas_assembly(root / "src/lib.c", arch))
        return ["-DCHECK_canvas_cells", str(root / "test/checks.c"), str(target)]


